select count(1) from insp_task
where tenant_id = #{tenantId}
  and plan_id = #{planId}
  and deleted = 0
  and status = 'PENDING'
  and scheduled_start >= #{windowStart}
  and scheduled_start <= #{windowEnd}

select count(1) as total_count, sum(case when status = 'PENDING' then 1 else 0 end) as pending_count, sum(case when status = 'IN_PROGRESS' then 1 else 0 end) as in_progress_count, sum(case when status = 'COMPLETED' then 1 else 0 end) as completed_count, sum(case when status = 'MISSED' then 1 else 0 end) as missed_count, coalesce(sum(abnormal_count), 0) as abnormal_item_count from insp_task where tenant_id = #{tenantId} and deleted = 0
and scheduled_start >= #{from}
